# 4. experiments
exps=r"""
,{id:`xa-phong-hoa`,title:`Xà phòng hóa chất béo`,grade:12,minutes:12,visual:`flask`,aim:`Thủy phân chất béo trong NaOH khi đun, tách xà phòng bằng NaCl bão hòa.`,materials:[`Dầu thực vật (triolein)`,`NaOH 40%`,`NaCl bão hòa`,`Bát sứ, đũa thủy tinh`,`Đèn cồn`],steps:[{id:`s1`,kind:`add`,reagentId:`triolein`,prompt:`Cho khoảng 1 g dầu thực vật vào bát sứ.`,success:`Chất béo là trieste của glixerol với axit béo, không tan trong nước.`,fail:`Cần chất béo (dầu thực vật).`},{id:`s2`,kind:`add`,reagentId:`naoh`,prompt:`Thêm 2–2,5 ml dung dịch NaOH 40%.`,success:`Chưa đun: dầu nổi thành lớp riêng, phản ứng rất chậm. NaOH đặc ăn mòn da — đeo kính, găng.`,fail:`Xà phòng hóa cần kiềm NaOH.`},{id:`s3`,kind:`heat`,prompt:`Đun sôi nhẹ 8–10 phút, khuấy đều, thỉnh thoảng thêm vài giọt nước cất.`,success:`Hỗn hợp đồng nhất dần: (C17H33COO)3C3H5 + 3NaOH → 3C17H33COONa + C3H5(OH)3. Bổ sung nước để hỗn hợp không cạn, tránh bắn kiềm nóng.`},{id:`s4`,kind:`add`,reagentId:`nacl`,prompt:`Rót 4–5 ml NaCl bão hòa nóng, khuấy nhẹ rồi để nguội.`,success:`Lớp chất rắn trắng nhẹ nổi lên trên — đó là xà phòng. NaCl làm giảm độ tan của muối natri axit béo (tách muối) và tăng khối lượng riêng lớp dưới.`,fail:`Dùng NaCl bão hòa để tách xà phòng.`},{id:`s5`,kind:`observe`,prompt:`Quan sát lớp trên và lớp dưới.`,note:`Lớp trên: muối natri của axit béo (xà phòng). Lớp dưới: glixerol, NaCl, NaOH dư. Không chạm tay vào sản phẩm — còn kiềm dư.`},{id:`s6`,kind:`choice`,prompt:`Xà phòng hóa hoàn toàn 1 mol triolein cần bao nhiêu mol NaOH?`,options:[`1 mol`,`2 mol`,`3 mol`,`6 mol`],correct:2,explain:`Triolein có 3 nhóm este, mỗi nhóm cần 1 NaOH. Thu được 3 mol C17H33COONa và 1 mol glixerol.`},{id:`s7`,kind:`conclude`,summary:`Chất béo + NaOH (đun) → muối natri của axit béo (xà phòng) + glixerol. Phản ứng một chiều, khác thủy phân trong axit.`,equation:`(C17H33COO)3C3H5 + 3NaOH → 3C17H33COONa + C3H5(OH)3`}]}
,{id:`trang-bac-glucozo`,title:`Phản ứng tráng bạc của glucozơ`,grade:12,minutes:8,visual:`tube`,aim:`Chứng minh glucozơ có nhóm –CHO; so sánh với saccarozơ.`,materials:[`AgNO3 1%`,`NH3 5%`,`Glucozơ 1%`,`Ống nghiệm sạch`,`Cốc nước nóng`],steps:[{id:`s1`,kind:`add`,reagentId:`agno3`,prompt:`Cho 1 ml AgNO3 1% vào ống nghiệm thật sạch (rửa trước bằng NaOH, tráng nước cất).`,success:`Ống sạch dầu mỡ thì bạc mới bám thành lớp gương đều. AgNO3 làm đen da — đeo găng.`,fail:`Bắt đầu với AgNO3.`},{id:`s2`,kind:`add`,reagentId:`nh3`,prompt:`Nhỏ từng giọt NH3, lắc, đến khi kết tủa nâu xám vừa tan hết.`,success:`Thu được phức [Ag(NH3)2]OH (thuốc thử Tollens), dung dịch trong. Không để dư nhiều NH3.`,fail:`Cần NH3 để tạo phức bạc–amoniac.`},{id:`s3`,kind:`add`,reagentId:`glucose`,prompt:`Thêm 1 ml dung dịch glucozơ.`,success:`Glucozơ dạng mạch hở có nhóm –CHO. Chưa đun thì gần như chưa thấy bạc.`,fail:`Chất khử ở bài này là glucozơ.`},{id:`s4`,kind:`heat`,prompt:`Ngâm ống trong cốc nước nóng 60–70 °C vài phút, không lắc.`,success:`Thành ống phủ lớp bạc sáng như gương. Không đun trực tiếp trên lửa; đổ bỏ thuốc thử ngay sau thí nghiệm vì để lâu có thể tạo hợp chất bạc dễ nổ.`},{id:`s5`,kind:`choice`,prompt:`Tráng bạc hoàn toàn 0,1 mol glucozơ thu được bao nhiêu mol Ag?`,options:[`0,1 mol`,`0,2 mol`,`0,4 mol`,`0,05 mol`],correct:1,explain:`Một nhóm –CHO → –COO-, nhường 2e, khử 2Ag+. n(Ag) = 2n(glucozơ) = 0,2 mol.`},{id:`s6`,kind:`choice`,prompt:`Chất nào không tráng bạc?`,options:[`Glucozơ`,`Fructozơ (trong môi trường kiềm)`,`Saccarozơ`,`Axit fomic`],correct:2,explain:`Saccarozơ không còn nhóm –OH hemiaxetal nên không mở vòng tạo –CHO. Fructozơ chuyển thành glucozơ trong môi trường kiềm nên vẫn tráng bạc.`},{id:`s7`,kind:`conclude`,summary:`Glucozơ có nhóm –CHO, khử [Ag(NH3)2]+ thành Ag khi đun nhẹ. Saccarozơ âm tính; sau thủy phân trong axit thì dương tính.`,equation:`C6H12O6 + 2[Ag(NH3)2]OH → C6H12O7 + 2Ag↓ + 4NH3 + H2O`}]}
,{id:`glucozo-cuoh2`,title:`Glucozơ với Cu(OH)2`,grade:12,minutes:8,visual:`tube`,aim:`Chứng minh glucozơ có nhiều nhóm –OH kề nhau (lạnh) và nhóm –CHO (đun nóng).`,materials:[`CuSO4 5%`,`NaOH 10%`,`Glucozơ 1%`,`Ống nghiệm`,`Đèn cồn`],steps:[{id:`s1`,kind:`add`,reagentId:`cuso4`,prompt:`Cho vài giọt CuSO4 5% vào ống nghiệm.`,success:`Dung dịch xanh lam của ion Cu2+.`,fail:`Bắt đầu với CuSO4.`},{id:`s2`,kind:`add`,reagentId:`naoh`,prompt:`Thêm 1 ml NaOH 10%, lắc nhẹ.`,success:`Kết tủa xanh lơ Cu(OH)2: CuSO4 + 2NaOH → Cu(OH)2↓ + Na2SO4. NaOH dư để môi trường kiềm.`,fail:`Cần NaOH để tạo Cu(OH)2.`},{id:`s3`,kind:`add`,reagentId:`glucose`,prompt:`Thêm 2 ml glucozơ, lắc ở nhiệt độ thường.`,success:`Kết tủa tan, dung dịch xanh lam thẫm: 2C6H12O6 + Cu(OH)2 → (C6H11O6)2Cu + 2H2O. Tính chất của ancol đa chức.`,fail:`Thêm glucozơ.`},{id:`s4`,kind:`heat`,prompt:`Đun nóng nhẹ ống nghiệm (hướng miệng ống ra xa người).`,success:`Xuất hiện kết tủa đỏ gạch Cu2O: nhóm –CHO khử Cu(II) thành Cu(I) trong môi trường kiềm.`},{id:`s5`,kind:`choice`,prompt:`Chất nào hòa tan Cu(OH)2 ở nhiệt độ thường nhưng không tạo Cu2O khi đun?`,options:[`Glucozơ`,`Saccarozơ`,`Anđehit fomic`,`Ancol etylic`],correct:1,explain:`Saccarozơ có nhiều –OH kề nhau (dung dịch xanh lam) nhưng không có –CHO. Ancol etylic đơn chức không hòa tan Cu(OH)2.`},{id:`s6`,kind:`conclude`,summary:`Lạnh: glucozơ hòa tan Cu(OH)2 → dung dịch xanh lam (nhiều –OH kề). Đun nóng trong kiềm: Cu2O đỏ gạch (có –CHO).`,equation:`2C6H12O6 + Cu(OH)2 → (C6H11O6)2Cu + 2H2O`}]}
,{id:`biure-protein`,title:`Phản ứng màu biure của protein`,grade:12,minutes:6,visual:`tube`,aim:`Nhận biết protein bằng Cu(OH)2 trong môi trường kiềm — màu tím đặc trưng.`,materials:[`Lòng trắng trứng`,`NaOH 30%`,`CuSO4 2%`,`Ống nghiệm`],steps:[{id:`s1`,kind:`add`,reagentId:`protein`,prompt:`Cho 1 ml dung dịch lòng trắng trứng vào ống nghiệm.`,success:`Protein (anbumin) tạo dung dịch keo.`,fail:`Cần lòng trắng trứng.`},{id:`s2`,kind:`add`,reagentId:`naoh`,prompt:`Thêm 1 ml NaOH 30%. Cẩn thận: kiềm đặc ăn mòn, đeo kính bảo hộ.`,success:`Môi trường kiềm mạnh, cần cho phản ứng biure.`,fail:`Phản ứng biure cần môi trường kiềm.`},{id:`s3`,kind:`add`,reagentId:`cuso4`,prompt:`Nhỏ 1 giọt CuSO4 2%, lắc.`,success:`Dung dịch chuyển màu tím: Cu(OH)2 tạo phức với các nhóm peptit –CO–NH–.`,fail:`Thuốc thử là CuSO4 trong kiềm (Cu(OH)2).`},{id:`s4`,kind:`observe`,prompt:`Ghi lại màu tím. Chỉ nhỏ ít CuSO4.`,note:`Nhỏ quá nhiều CuSO4 sẽ có kết tủa xanh Cu(OH)2 che màu tím. Đun lòng trắng trứng (hoặc thêm axit, muối kim loại nặng) thì protein đông tụ.`},{id:`s5`,kind:`choice`,prompt:`Chất nào không cho phản ứng màu biure?`,options:[`Lòng trắng trứng`,`Tripeptit Gly-Ala-Gly`,`Đipeptit Gly-Ala`,`Polipeptit`],correct:2,explain:`Cần từ 2 liên kết peptit trở lên (tripeptit trở lên). Đipeptit chỉ có 1 liên kết peptit nên không tạo màu tím.`},{id:`s6`,kind:`conclude`,summary:`Protein và peptit (từ tripeptit) + Cu(OH)2/OH- → phức màu tím. Đipeptit và amino axit âm tính.`,equation:`Protein + Cu(OH)2 (OH-) → phức màu tím`}]}
,{id:`dien-phan-cuso4`,title:`Điện phân dung dịch CuSO4`,grade:12,minutes:10,visual:`cell`,aim:`Xác định sản phẩm ở catot, anot khi điện phân CuSO4 với điện cực trơ (than chì).`,materials:[`CuSO4 0,5 M`,`Hai điện cực than chì`,`Nguồn một chiều 6 V`,`Dây dẫn`,`Cốc thủy tinh`],steps:[{id:`s1`,kind:`add`,reagentId:`cuso4`,prompt:`Rót dung dịch CuSO4 vào cốc, nhúng hai điện cực than chì.`,success:`Dung dịch xanh lam chứa Cu2+, SO4^2- và H2O.`,fail:`Chất điện phân ở bài này là CuSO4.`},{id:`s2`,kind:`observe`,prompt:`Nối điện cực với nguồn 6 V một chiều vài phút. Ngắt nguồn trước khi chạm vào điện cực.`,note:`Catot (cực −): lớp đồng đỏ bám vào. Anot (cực +): bọt khí không màu (O2). Màu xanh nhạt dần vì Cu2+ giảm. Làm nơi thoáng, không dùng nguồn điện xoay chiều.`},{id:`s3`,kind:`choice`,prompt:`Quá trình ở anot (điện cực trơ) là`,options:[`Cu → Cu2+ + 2e`,`2H2O → O2 + 4H+ + 4e`,`2SO4^2- → S2O8^2- + 2e`,`Cu2+ + 2e → Cu`],correct:1,explain:`SO4^2- không bị oxi hóa trong dung dịch; nước bị oxi hóa thành O2. Nếu anot là Cu (anot tan) thì Cu mới tan ra.`},{id:`s4`,kind:`choice`,prompt:`Sau điện phân, quỳ tím nhúng vào dung dịch đổi màu`,options:[`Xanh`,`Đỏ`,`Không đổi`,`Mất màu`],correct:1,explain:`Tạo H2SO4 (H+ sinh ra ở anot) nên dung dịch có môi trường axit.`},{id:`s5`,kind:`choice`,prompt:`Điện phân với I = 1,93 A trong 1000 s, khối lượng Cu bám catot là`,options:[`0,32 g`,`0,64 g`,`1,28 g`,`0,16 g`],correct:1,explain:`m = A·I·t/(n·F) = 64·1,93·1000/(2·96500) = 0,64 g.`},{id:`s6`,kind:`conclude`,summary:`Điện phân dung dịch CuSO4 (điện cực trơ): catot Cu2+ + 2e → Cu; anot 2H2O → O2 + 4H+ + 4e. Dung dịch hóa axit. Ứng dụng: mạ đồng, tinh chế đồng (anot Cu).`,equation:`2CuSO4 + 2H2O → 2Cu + O2 + 2H2SO4`}]}
,{id:`nhan-biet-fe2-fe3`,title:`Nhận biết Fe2+ và Fe3+`,grade:12,minutes:8,visual:`tube`,aim:`Dùng KSCN và NaOH để phân biệt muối sắt(II) và sắt(III).`,materials:[`FeCl3`,`FeSO4 (mới pha)`,`KSCN`,`NaOH`,`Ống nghiệm`],steps:[{id:`s1`,kind:`add`,reagentId:`fecl3`,prompt:`Cho 1 ml dung dịch FeCl3 (vàng nâu) vào ống nghiệm.`,success:`Ion Fe3+ cho dung dịch màu vàng nâu.`,fail:`Bắt đầu với muối sắt(III).`},{id:`s2`,kind:`add`,reagentId:`kscn`,prompt:`Nhỏ 1–2 giọt KSCN.`,success:`Dung dịch đỏ máu: Fe3+ + 3SCN- → Fe(SCN)3. Phép thử rất nhạy của Fe3+. Không trộn KSCN với axit đặc.`,fail:`Thuốc thử đặc trưng của Fe3+ là SCN-.`},{id:`s3`,kind:`observe`,prompt:`Làm song song với FeSO4 mới pha + KSCN, rồi thêm NaOH vào một ống FeSO4 khác.`,note:`FeSO4 + KSCN: không đỏ (hơi hồng nếu Fe2+ đã bị oxi hóa). FeSO4 + NaOH: kết tủa trắng xanh Fe(OH)2, để ngoài không khí hóa nâu đỏ: 4Fe(OH)2 + O2 + 2H2O → 4Fe(OH)3.`},{id:`s4`,kind:`choice`,prompt:`Nhỏ NaOH vào dung dịch FeCl3, hiện tượng là`,options:[`Kết tủa trắng xanh`,`Kết tủa nâu đỏ`,`Dung dịch đỏ máu`,`Có khí thoát ra`],correct:1,explain:`FeCl3 + 3NaOH → Fe(OH)3↓ (nâu đỏ) + 3NaCl.`},{id:`s5`,kind:`choice`,prompt:`Thuốc thử nào làm mất màu tím khi gặp Fe2+ nhưng không đổi khi gặp Fe3+ (môi trường H2SO4)?`,options:[`KSCN`,`KMnO4`,`NaCl`,`BaCl2`],correct:1,explain:`Fe2+ có tính khử: MnO4- + 5Fe2+ + 8H+ → Mn2+ + 5Fe3+ + 4H2O. Fe3+ không còn bị oxi hóa.`},{id:`s6`,kind:`conclude`,summary:`Fe3+: KSCN → đỏ máu; NaOH → Fe(OH)3 nâu đỏ. Fe2+: NaOH → Fe(OH)2 trắng xanh, hóa nâu trong không khí; làm mất màu KMnO4/H+.`,equation:`Fe3+ + 3SCN- → Fe(SCN)3`}]}
""".replace("\n","")
