topics=r"""
,{id:`kim-loai-12`,title:`Kim loại kiềm, kiềm thổ, nhôm, sắt`,grade:12,blurb:`Tính khử, nước cứng, lưỡng tính, Fe2+/Fe3+.`,sections:[{heading:`Kim loại kiềm và kiềm thổ`,body:`Nhóm IA (Li, Na, K…) có 1e lớp ngoài, tính khử rất mạnh, tác dụng nước ở nhiệt độ thường: 2Na + 2H2O → 2NaOH + H2. Bảo quản Na, K trong dầu hỏa. Nhóm IIA: Be không tác dụng với nước, Mg tác dụng chậm với nước nóng; Ca, Sr, Ba tác dụng ở nhiệt độ thường. Điều chế bằng điện phân nóng chảy muối clorua.`},{heading:`Nước cứng`,body:`Chứa nhiều Ca2+, Mg2+. Tạm thời: có HCO3- (đun sôi làm mềm: Ca(HCO3)2 → CaCO3↓ + CO2 + H2O). Vĩnh cửu: có Cl-, SO4^2-. Na2CO3 và Na3PO4 làm mềm được cả hai loại.`},{heading:`Nhôm`,body:`Al tan trong axit và trong dung dịch kiềm (giải phóng H2). Al bị thụ động trong HNO3 đặc nguội và H2SO4 đặc nguội. Al2O3, Al(OH)3 lưỡng tính. Điều chế Al bằng điện phân nóng chảy Al2O3 có criolit.`},{heading:`Sắt`,body:`Fe tác dụng HCl, H2SO4 loãng cho Fe2+; với HNO3, H2SO4 đặc nóng cho Fe3+. Fe2+ vừa khử vừa oxi hóa; Fe3+ có tính oxi hóa (Fe + 2Fe3+ → 3Fe2+). Nhận biết Fe3+ bằng SCN- (đỏ máu), Fe2+ bằng NaOH (trắng xanh hóa nâu).`}],questions:[{id:`kl-1`,prompt:`Kim loại nào được bảo quản bằng cách ngâm trong dầu hỏa?`,options:[`Al`,`Na`,`Fe`,`Cu`],correct:1,explain:`Na phản ứng mạnh với O2 và hơi nước trong không khí. Dầu hỏa ngăn tiếp xúc.`},{id:`kl-2`,prompt:`Chất làm mềm được cả nước cứng tạm thời và vĩnh cửu là`,options:[`NaCl`,`Ca(OH)2`,`Na2CO3`,`HCl`],correct:2,explain:`CO3^2- kết tủa cả Ca2+ và Mg2+. Ca(OH)2 vừa đủ chỉ làm mềm nước cứng tạm thời.`},{id:`kl-3`,prompt:`Nhỏ từ từ NaOH đến dư vào dung dịch AlCl3, hiện tượng là`,options:[`Không hiện tượng`,`Kết tủa keo trắng rồi tan`,`Kết tủa keo trắng không tan`,`Có khí thoát ra`],correct:1,explain:`Al(OH)3 tạo ra rồi tan trong NaOH dư: Al(OH)3 + NaOH → Na[Al(OH)4].`},{id:`kl-4`,prompt:`Kim loại bị thụ động trong HNO3 đặc nguội là`,options:[`Cu`,`Ag`,`Al và Fe`,`Mg`],correct:2,explain:`Al, Fe, Cr bị thụ động hóa trong HNO3 đặc nguội và H2SO4 đặc nguội.`},{id:`kl-5`,prompt:`Thuốc thử nhận biết ion Fe3+ cho màu đỏ máu là`,options:[`KSCN`,`BaCl2`,`AgNO3`,`Phenolphtalein`],correct:0,explain:`Fe3+ + 3SCN- → Fe(SCN)3 màu đỏ máu.`}]},{id:`amin-polime`,title:`Amin, amino axit, polime`,grade:12,blurb:`Tính bazơ của amin, lưỡng tính amino axit, trùng hợp và trùng ngưng.`,sections:[{heading:`Amin`,body:`Amin có tính bazơ do cặp e tự do trên N: CH3NH2 làm quỳ hóa xanh. Anilin C6H5NH2 bazơ rất yếu, không làm đổi màu quỳ, nhưng tác dụng với nước brom tạo kết tủa trắng 2,4,6-tribromanilin.`},{heading:`Amino axit`,body:`Có cả –NH2 và –COOH nên lưỡng tính, tồn tại dạng ion lưỡng cực. Glyxin H2N–CH2–COOH tác dụng với cả HCl và NaOH. Trùng ngưng amino axit tạo poliamit.`},{heading:`Polime`,body:`Trùng hợp: monome có liên kết bội hoặc vòng kém bền (PE, PVC, PS, cao su buna). Trùng ngưng: monome có ít nhất hai nhóm chức, tách phân tử nhỏ như H2O (nilon-6,6, tơ lapsan). Tơ tằm, len là tơ thiên nhiên; tơ visco, axetat là tơ bán tổng hợp.`}],questions:[{id:`ap-1`,prompt:`Dung dịch chất nào làm quỳ tím hóa xanh?`,options:[`Anilin`,`Metylamin`,`Glyxin`,`Phenol`],correct:1,explain:`Metylamin là bazơ mạnh hơn NH3. Anilin bazơ quá yếu; glyxin có số –NH2 bằng số –COOH nên gần trung tính.`},{id:`ap-2`,prompt:`Polime nào được điều chế bằng phản ứng trùng ngưng?`,options:[`Polietilen`,`PVC`,`Nilon-6,6`,`Polistiren`],correct:2,explain:`Nilon-6,6 từ hexametylenđiamin và axit ađipic, tách H2O. Ba chất còn lại trùng hợp.`},{id:`ap-3`,prompt:`Anilin tác dụng với nước brom tạo`,options:[`Dung dịch xanh`,`Kết tủa trắng`,`Khí không màu`,`Kết tủa vàng`],correct:1,explain:`C6H5NH2 + 3Br2 → C6H2Br3NH2↓ (trắng) + 3HBr.`},{id:`ap-4`,prompt:`Glyxin không tác dụng với chất nào?`,options:[`HCl`,`NaOH`,`C2H5OH (xúc tác HCl)`,`NaCl`],correct:3,explain:`Glyxin lưỡng tính: phản ứng với axit, bazơ, và este hóa với ancol khi có HCl khí. NaCl không phản ứng.`}]}
""".replace("\n","")
rep("explain:`Cu đứng sau H trong dãy điện hóa.`}]}]","explain:`Cu đứng sau H trong dãy điện hóa.`},{id:`dh-4`,prompt:`Điện phân dung dịch CuSO4 với điện cực trơ, ở anot thu được`,options:[`Cu`,`H2`,`O2`,`SO2`],correct:2,explain:`Nước bị oxi hóa ở anot: 2H2O → O2 + 4H+ + 4e. Cu bám ở catot.`}]}"+topics+"]")
